export const SPRITE_BOX={width:192,height:224,baseline:140};
const small=new Set([25]),medium=new Set([6,9,254,257,260,282,448,658]),large=new Set([144,145,146,149,150,243,244,245,373,376,445]);
export const legendaryIds=new Set([144,145,146,150,151,243,244,245,249,250,251,377,378,379,380,381,382,383,384,385,386,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,638,639,640,641,642,643,644,645,646,647,648,649,716,717,718,719,720,721,785,786,787,788,789,790,791,792,800,801,802,807,808,809,888,889,890,891,892,893,894,895,896,897,898,905,1001,1002,1003,1004,1007,1008,1014,1015,1016,1017,1024,1025]);
export function spriteExtent(id,mega=false,raid=false){const base=id===890?128:(raid&&legendaryIds.has(id))?106:small.has(id)?62:medium.has(id)?82:large.has(id)?94:id>=380?100:86;return mega?(id===890?144:Math.min(122,Math.round(base*1.16))):base}
let scratch;const metrics=new WeakMap();
function canvas(){scratch??=document.createElement('canvas');return scratch}
export function visibleBounds(image,rect){let map=metrics.get(image);if(!map){map=new Map();metrics.set(image,map)}const key=[rect.x,rect.y,rect.width,rect.height].join(',');if(map.has(key))return map.get(key);const s=canvas();s.width=rect.width;s.height=rect.height;const c=s.getContext('2d',{willReadFrequently:true});let bounds={x:0,y:0,width:rect.width,height:rect.height};try{c.clearRect(0,0,s.width,s.height);c.drawImage(image,rect.x,rect.y,rect.width,rect.height,0,0,s.width,s.height);const d=c.getImageData(0,0,s.width,s.height).data;let left=s.width,top=s.height,right=-1,bottom=-1;for(let y=0;y<s.height;y++)for(let x=0;x<s.width;x++)if(d[(y*s.width+x)*4+3]>12){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y)}if(right>=left&&bottom>=top)bounds={x:left,y:top,width:right-left+1,height:bottom-top+1};}catch{}map.set(key,bounds);return bounds}
const animationMetrics=new WeakMap();
export function animationBounds(image,anim,row){let map=animationMetrics.get(image);if(!map){map=new Map();animationMetrics.set(image,map)}const key=[anim.width,anim.height,row,anim.durations.length].join(',');if(map.has(key))return map.get(key);let left=anim.width,top=anim.height,right=0,bottom=0;for(let f=0;f<anim.durations.length;f++){const b=visibleBounds(image,{x:f*anim.width,y:row*anim.height,width:anim.width,height:anim.height});left=Math.min(left,b.x);top=Math.min(top,b.y);right=Math.max(right,b.x+b.width);bottom=Math.max(bottom,b.y+b.height)}const b={x:left,y:top,width:Math.max(1,right-left),height:Math.max(1,bottom-top)};map.set(key,b);return b}
export function spriteLayout(id,reference,pose=reference,mega=false,raid=false){const scale=Math.min(spriteExtent(id,mega,raid)/Math.max(1,reference.width,reference.height),(SPRITE_BOX.width-4)/Math.max(1,pose.width),(SPRITE_BOX.height-8)/Math.max(1,pose.height));return{scale,x:SPRITE_BOX.width/2-(pose.x+pose.width/2)*scale,y:SPRITE_BOX.baseline-(pose.y+pose.height)*scale}}
export function paintSprite(canvas,image,rect,id,reference,pose,mega=false,raid=false){if(canvas.width!==SPRITE_BOX.width)canvas.width=SPRITE_BOX.width;if(canvas.height!==SPRITE_BOX.height)canvas.height=SPRITE_BOX.height;const c=canvas.getContext('2d'),layout=spriteLayout(id,reference,pose,mega,raid);c.imageSmoothingEnabled=false;c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(image,rect.x,rect.y,rect.width,rect.height,layout.x,layout.y,rect.width*layout.scale,rect.height*layout.scale);canvas.style.width=SPRITE_BOX.width/129.6*100+'%';canvas.style.height=SPRITE_BOX.height/129.6*100+'%';canvas.dataset.visibleExtent=String(Math.round(Math.max(reference.width,reference.height)*layout.scale));canvas.dataset.bodyTop=String(layout.y+pose.y*layout.scale-SPRITE_BOX.height/2);canvas.dataset.bodyHeight=String(pose.height*layout.scale);canvas.dataset.bodyWidth=String(pose.width*layout.scale);return layout}
